    "Q56": [
      { minScore: 0, maxScore: 4, text: "A long-term goal for the organization gives everyone a clear framework for strategy and decisions - and can be very motivating. With a company of your size, it's really necessary for things to be clear, set down on paper and shared." },
      { minScore: 5, maxScore: 6, text: "A long-term goal for the organization gives everyone a clear framework for strategy and decisions - and can be very motivating. Good that you have started doing this. It's important for you to finish this quickly." },
      { minScore: 7, maxScore: 8, text: "A long-term goal for the organization gives everyone a clear framework for strategy and decisions - and can be very motivating. Good that you have already come a long way with this." },
      { minScore: 9, maxScore: 10, text: "A long-term goal for the organization gives everyone a clear framework for strategy and decisions - and can be very motivating. Great that this is already all in place. Ensure you check this annually - verifying a valid long-term goal." },
    ],
    "Q57": [
      { minScore: 0, maxScore: 4, text: "Focusing on goals, including annual goals, provides direction and a framework to your business activities. In addition, this information motivates your employees. In this phase you should make all of this a bit clearer." },
      { minScore: 5, maxScore: 6, text: "Focusing on goals, including annual goals, provides direction and a framework to your business activities. In addition, this information motivates your employees. Good that you have already started doing this; try to persevere and especially to communicate about this on a regular basis." },
      { minScore: 7, maxScore: 8, text: "Focusing on goals, including annual goals, provides direction and a framework to your business activities. In addition, this information motivates your employees. Good that you have already come a long way with this. Above all try to keep your goals \"alive\"." },
      { minScore: 9, maxScore: 10, text: "Focusing on goals, including annual goals, provides direction and a framework to your business activities. In addition, this information motivates your employees. Fantastic that everyone knows what the annual goal is. Well done!" },
    ],
    "Q58": [
      { minScore: 0, maxScore: 4, text: "Focusing on goals, including monthly goals and KPIs, provides guidance and direction to business activities. Actually, you make a small sprint every month to ensure that you are \"on schedule\". The clearer the goal the clearer it becomes on how to achieve it. In your phase it helps when everyone knows which goal should be achieved. Perhaps you can start on this immediately!" },
      { minScore: 5, maxScore: 6, text: "Focusing on goals, including monthly goals and KPIs, provides guidance and direction to business activities. Actually, you make a small sprint every month to ensure that you are \"on schedule\". The clearer the goal the clearer it becomes on how to achieve it. Good that you have already started doing this. Hurry up and finish and implement it." },
      { minScore: 7, maxScore: 8, text: "Focusing on goals, including monthly goals and KPIs, provides guidance and direction to business activities. Actually, you make a small sprint every month to ensure that you are \"on schedule\". The clearer the goal the clearer it becomes on how to achieve it. Good that you are already applying this. Think above all about clear and simple communication with respect to the goals." },
      { minScore: 9, maxScore: 10, text: "Focusing on goals, including monthly goals and KPIs, provides guidance and direction to business activities. Actually, you make a small sprint every month to ensure that you are \"on schedule\". The clearer the goal the clearer it becomes on how to achieve it. Great that you have got this all together. Well done." },
    ],
