/** Build a mutable version-payload shape without exposing the frozen catalogue arrays. */
export function buildPhaseRecommendations(
  stableKey: string,
): PhaseRecommendation[] {
  const bandsForFirstPhase = SU_FULL_PHASE_FEEDBACK[1][stableKey];
  if (!bandsForFirstPhase) {
    throw new Error(
      `Unknown canonical Scaling Up Full question key: ${JSON.stringify(stableKey)}.`,
    );
  }

  return ([1, 2, 3, 4, 5] as const).map((phase) => ({
    phase,
    bands: SU_FULL_PHASE_FEEDBACK[phase][stableKey].map((band) => ({ ...band })),
  }));
}
